mapper.select:
SELECT id, wallet_id, user_id, balance, frozen_amount, create_time, update_time
FROM virtual_wallet
WHERE user_id = #{userId}

mapper.update:
UPDATE virtual_wallet
SET frozen_amount = frozen_amount + #{amount},
    update_time   = NOW()
WHERE user_id = #{userId}
  AND balance - frozen_amount >= #{amount}

mapper.select:
SELECT id, wallet_id, user_id, type, amount, order_id, biz_round, create_time, update_time
FROM wallet_detail
WHERE user_id = #{userId}
ORDER BY id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1)
FROM wallet_detail
WHERE user_id = #{userId}
